payload.consulta:
SELECT ?c ?tipo ?rotulo ?lang WHERE {
  GRAPH <http://vocabularies.unesco.org/thesaurus/> {
    { ?c skos:prefLabel ?l . BIND("prefLabel" AS ?tipo) }
    UNION
    { ?c skos:altLabel ?l . BIND("altLabel" AS ?tipo) }
    FILTER(LCASE(STR(?l)) = "educational")
    ?c skos:prefLabel ?rotulo .
    BIND(LANG(?rotulo) AS ?lang)
  }
} LIMIT 60
